async function main() {
  let backendPromise = null;
  let backendRef = null;
  const getBackend = () => {
    if (!backendPromise) {
      backendPromise = createBackend().then(
        (b) => {
          backendRef = b;
          return b;
        },
        (e) => {
          backendPromise = null;
          throw e;
        }
      );
    }
    return backendPromise;
  };
  const server = createServer(getBackend);
  const transport = new StdioServerTransport();
  await server.connect(transport);
  logInfo(`shamela-mcp v${VERSION} ready (30 tools + 5 resources registered)`);
  void getBackend().then(() => logInfo("backend warmed (JVM + indexes ready)")).catch((e) => logInfo(`warm-up deferred to first call: ${formatErrorMessage(e)}`));
  const shutdown = () => {
    backendRef?.helper.close();
    backendRef?.pages.close();
    backendRef?.services.close();
  };
  process.on("SIGTERM", shutdown);
  process.on("SIGINT", shutdown);
}
var isEntry = (() => {
  if (!process.argv[1]) return false;
  try {
    return import.meta.url === pathToFileURL(process.argv[1]).href;
  } catch {
    return false;
  }
})();
if (isEntry) {
  main().catch((err) => {
    process.stderr.write(`[shamela-mcp] fatal: ${formatErrorMessage(err)}
`);
    process.exit(1);
  });
}
export {
  createBackend,
  createServer
};
